<?php $title = t('modules.employees'); $section = 'employees'; require __DIR__ . '/header.php'; ?>
<div class="page-heading"><div><span class="eyebrow"><?= h(t('employees.hr')) ?></span><h1><?= h(t('employees.headline')) ?></h1><p class="muted"><?= h(t('employees.intro')) ?></p></div><?php if ($canCreate): ?><a class="button primary" href="/employees/new">＋ <?= h(t('nav.add_employee')) ?></a><?php endif; ?></div>
