<div class="table-scroll"><table><thead><tr><th><?= h(t('employees.person')) ?></th><th><?= h(t('employees.number')) ?></th><th><?= h(t('employees.state')) ?></th><th><?= h(t('employees.created_date')) ?></th><th><span class="sr-only"><?= h(t('common.actions')) ?></span></th></tr></thead><tbody>
