<?php if ($result['rows'] === []): ?><tr><td colspan="5"><div class="empty"><h3><?= $search === '' ? t('employees.empty_title') : t('employees.no_results') ?></h3><p class="muted"><?= $search === '' ? t('employees.empty_text') : t('employees.search_again') ?></p></div></td></tr><?php endif; ?>
